<?php
namespace qqworld_collector\module\collect_item; use qqworld_collector\lib; class comment_author_url extends lib { var $guid; public function init() { add_filter( 'qqworld-collector-collecting-engine-collect-item-' . $this->guid, array($this, 'filter'), 10, 7 ); add_filter( 'qqworld-collector-collecting-engine-collect-item-after-filter-' . $this->guid, array($this, 'filter_after'), 10, 6 ); } public function filter($items, $args, $source_link, $html, $download_args, $settings, $mode) { return $items; } public function filter_after($items, $args, $source_link, $html, $settings, $mode) { if (!empty($items)) { $strip_tags = isset($args['strip-tags']) ? $args['strip-tags'] : 1; if ($strip_tags) $items = strip_tags($items); } return $items; } } ?>